with valid as (select id, customer_id, order_date, status, amount, discount, shipping_fee, round(shipping_fee, 0) shipping_fee_rounded, case when status = 'PENDING' then 1 else 0 end is_pending from orders where discount is not null and order_date >= date '2023-08-21') select id, amount, discount, shipping_fee, shipping_fee_rounded, min(discount) over (partition by customer_id order by order_date, id rows between 2 preceding and current row) last3_min_discount, max(discount) over (partition by customer_id order by order_date, id rows between 2 preceding and current row) last3_max_discount, sum(discount) over (partition by customer_id order by order_date, id rows between 2 preceding and current row) last3_sum_discount from valid;
